// 로그인한 브라우저의 쿠키로 Confluence REST를 부른다 — 트리를 화면에서 펼치지 않는다(접힌 가지 · 늦게 그려지는 트리를 놓치지 않게)
const base = String(ctx.params.base).replace(/\/$/, '');
const get = async (path) => {
  const r = await page.context().request.get(base + path, { timeout: 60000 });
  if (!r.ok()) throw new Error(`${path} → HTTP ${r.status()}${r.status() === 401 ? ' — 로그인이 안 됐습니다' : ''}`);
  return r.json();
};
const norm = (s) => String(s).replace(/\s+/g, ' ').trim();
// 견줄 때는 너그럽게 — 전각 괄호 · 공백 · 대소문자 차이를 무시한다
const key = (s) => String(s).normalize('NFKC').replace(/\s+/g, '').toLowerCase();
const names = String(ctx.params.rootPath).split('>').map(norm).filter(Boolean);
const leaf = names[names.length - 1];
const space = String(ctx.params.spaceKey || '').trim();
const inSpace = space ? ` and space="${space}"` : '';
const q = (s) => s.replace(/"/g, '\\"');
const trail = (p) => [...(p.ancestors || []).map((a) => a.title), p.title].join(' > ');
const fits = (p) => key(p.title) === key(leaf) && names.slice(0, -1).every((n) => (p.ancestors || []).some((a) => key(a.title) === key(n)));
const tried = [];
const search = async (label, cql) => {
  const res = await get(`/rest/api/content/search?cql=${encodeURIComponent(cql)}&expand=ancestors,space&limit=100`);
  const hit = res.results.filter(fits);
  tried.push(`${label} ${res.results.length}개 중 맞음 ${hit.length}${res.results.length ? ` (${res.results.slice(0, 5).map((p) => `${p.type}:${trail(p)}`).join(' | ')})` : ''}`);
  ctx.log(`찾기 — ${tried[tried.length - 1]}`);
  return hit;
};
// 1) 제목 그대로(페이지) 2) 제목 그대로(종류 무관 — 폴더 같은 것) 3) 글자 검색(괄호 · 기호 없이)
let match = await search('제목=(페이지)', `type=page and title="${q(leaf)}"${inSpace}`);
if (match.length === 0) match = await search('제목=(종류 무관)', `title="${q(leaf)}"${inSpace}`);
const words = leaf.replace(/[\[\]()［］【】{}<>"'~*?:\\/^!-]/g, ' ').trim();
if (match.length === 0 && words) match = await search('글자 검색', `title~"${q(words)}"${inSpace}`);
// 4) 트리를 이름으로 내려가기 — 맨 앞 이름을 찾고 하위 페이지에서 다음 이름을 차례로 고른다
const children = async (id) => {
  const out = [];
  for (let start = 0; ; start += 200) {
    const res = await get(`/rest/api/content/${id}/child/page?limit=200&start=${start}`);
    out.push(...res.results);
    if (res.results.length < 200) break;
  }
  return out;
};
if (match.length === 0) {
  const top = names[0];
  const res = await get(`/rest/api/content/search?cql=${encodeURIComponent(`title="${q(top)}"${inSpace}`)}&expand=ancestors,space&limit=100`);
  const tops = res.results.filter((p) => key(p.title) === key(top));
  tried.push(`트리 내려가기 — 맨 앞 «${top}» ${tops.length}개`);
  for (const t of tops) {
    let cur = [t];
    for (const n of names.slice(1)) {
      const next = [];
      for (const c of cur) {
        const kids = await children(c.id);
        const hit = kids.filter((k) => key(k.title) === key(n));
        if (hit.length === 0) tried.push(`«${c.title}» 아래에 «${n}» 없음 — 하위: ${kids.map((k) => k.title).slice(0, 15).join(' · ') || '없음'}`);
        next.push(...hit.map((h) => ({ ...h, ancestors: [...(c.ancestors || []), { title: c.title }], space: t.space })));
      }
      cur = next;
    }
    match.push(...cur);
  }
  ctx.log(`찾기 — ${tried.slice(3).join(' / ')}`);
}
if (match.length !== 1) throw new Error(`«${ctx.params.rootPath}»에 맞는 페이지가 ${match.length}개입니다${match.length > 1 ? ` — ${match.map(trail).join(' | ')} (스페이스 키로 좁히세요)` : ''} — 찾아본 것: ${tried.join(' / ')}`);
const root = match[0];
// 제목의 «/»는 폴더가 되지 않게 바꾼다
const seg = (t) => norm(t).replace(/\//g, '_');
const pages = [];
const walk = async (id, title, path, depth) => {
  pages.push({ id: String(id), title, path, depth });
  for (const c of await children(id)) await walk(c.id, c.title, `${path}/${seg(c.title)}`, depth + 1);
};
await walk(root.id, root.title, seg(root.title), 0);
ctx.log(`${trail(root)} 아래 ${pages.length}쪽`);
return { pages, count: pages.length, rootId: String(root.id), space: root.space ? root.space.key : '' };

// 받은 페이지마다 REST로 본문(body.view — 화면에 그려지는 것)을 읽어, 위키 안의 그림 · 첨부 주소를 모은다(겹치면 하나로)
const base = String(ctx.params.base).replace(/\/$/, '');
const origin = new URL(base).origin;
const all = String(ctx.params.assets) === 'all';
const seen = new Map();
const add = (raw, pageId, kind) => {
  let u;
  try { u = new URL(raw.replace(/&amp;/g, '&'), base + '/'); } catch { return; }
  if (u.origin !== origin) return;
  // 첨부 · 썸네일 · 위키 아이콘만(페이지 · 액션 주소는 아니다)
  if (!/^\/(download\/(attachments|thumbnails)\/|images\/icons\/)/.test(u.pathname)) return;
  if (kind === 'link' && !all) return;
  const path = 'assets' + decodeURIComponent(u.pathname);
  if (!seen.has(path)) seen.set(path, { url: u.origin + u.pathname + u.search, path, pageId: String(pageId) });
};
let read = 0;
for (const r of input.rows || []) {
  if (r.ok === false) continue;
  const res = await page.context().request.get(`${base}/rest/api/content/${r.id}?expand=body.view`, { timeout: 60000 });
  if (!res.ok()) { ctx.log(`${r.title}: 본문을 읽지 못했습니다 — HTTP ${res.status()}`); continue; }
  read++;
  const html = ((await res.json()).body || {}).view?.value || '';
  for (const m of html.matchAll(/\s(src|data-image-src|href)="([^"]+)"/g)) add(m[2], r.id, m[1] === 'href' ? 'link' : 'image');
}
const assets = [...seen.values()];
ctx.log(`${read}쪽에서 그림 · 첨부 ${assets.length}개${all ? '' : '(그림만 — 첨부 링크는 위키를 가리킨다)'}`);
return { assets, count: assets.length };
